const $=s=>document.querySelector(s),x=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={token:'',project:null,active:'',dirty:false,counter:0,saving:false,render:null,fit:null,measured:false,ui:['en','zh-CN'].includes(new URLSearchParams(location.search).get('ui'))?new URLSearchParams(location.search).get('ui'):(localStorage.getItem('deckweft.visual.ui')||'en'),undo:[],redo:[],drafts:new Map(),snapshot:null};
const t=(en,cn)=>state.ui==='zh-CN'?cn:en,scene=()=>state.project?.plan.scenes.find(s=>s.id===state.active),profile=()=>state.project.document.visualBrief?.profile||{colorIntensity:'bold',typographicContrast:'expressive',density:'comfortable',motionIntensity:'off',imageEmphasis:'large'};
let workbench;
let selectedImage='',assetInspection=null,sourceEntries=[];
let previewTimer,sequence=0,candidateRun=0,candidateState=null,familyOverrides=Object.create(null);
function invalidateCandidates(){candidateRun++;candidateState=null;$('#candidateDialog').close();$('#largeCandidate').removeAttribute('src');$('#candidates').replaceChildren();$('#rhythm').disabled=true;$('#rhythmReport').replaceChildren();$('#candidateStatus').textContent=t('Compare to measure these exact pages.','请比较并测量当前完整文稿。');}

async function api(path,data,method='POST') {const response=await fetch(path,{method,headers:{Authorization:'Bearer '+state.token,...(data===undefined?{}:{'Content-Type':'application/json'})},...(data===undefined?{}:{body:JSON.stringify(data)})});if(!response.ok){const e=(await response.json()).error;throw Object.assign(new Error(e.message),e);}return response;}
async function json(path,data,method){return (await api(path,data,method)).json();}
function message(text,error=false){$('#message').textContent=text;$('#message').classList.toggle('error',error);}
function error(e){message(e.message,true);}
function status(){const p=state.project;$('#emptyCanvas').hidden=!!p;$('#frameSpace').hidden=!p;$('#inspectorToggle').disabled=!p;$('#previousScene').disabled=!p||p.plan.scenes[0].id===state.active;$('#nextScene').disabled=!p||p.plan.scenes.at(-1).id===state.active;$('#workbenchWatch').disabled=!state.render||!state.measured;$('#save').disabled=!p||!state.dirty||state.saving||!!state.drafts.size;$('#exportHTML').disabled=!p||state.saving||!state.measured||!!state.drafts.size||(!!p?.extensions.deckweftWorkbench&&!workbench?.ready());$('#undo').disabled=!state.undo.length;$('#redo').disabled=!state.redo.length;$('#backup').disabled=!p;$('#history').disabled=!p;$('#fit').textContent=!p?'':state.drafts.size?t('Unapplied field edits need repair.','请修复尚未应用的字段修改。'):state.measured?t('✓ Fonts, images and DOM layout measured in this browser','✓ 已在当前浏览器测量字体、图片与 DOM 排版'):t('Rendering and measuring…','正在渲染与测量…');$('#resetDraft').hidden=!state.drafts.size;$('#useInteractionOpening').disabled=!state.measured||!!state.drafts.size;}
function changed(fn,{fields=false}={}) {if(!state.project)return;const before=structuredClone(state.project);fn();if(JSON.stringify(before)===JSON.stringify(state.project))return;invalidateCandidates();state.undo.push(before);if(state.undo.length>60)state.undo.shift();state.redo=[];state.counter++;state.dirty=true;state.measured=false;drawScenes();if(fields)drawEditor();status();schedulePreview();message(t('Unsaved changes','尚未保存'));return true;}
function moveHistory(redo=false){invalidateCandidates();const from=redo?state.redo:state.undo,to=redo?state.undo:state.redo;if(!from.length)return;const rev=state.project.revision;to.push(structuredClone(state.project));state.project=from.pop();state.project.revision=rev;state.active=state.project.plan.scenes.some(s=>s.id===state.active)?state.active:state.project.plan.scenes[0].id;state.counter++;state.dirty=true;draw();schedulePreview();}
function translate(){document.documentElement.lang=state.ui;for(const [id,en,zh]of [['previousScene','Previous page','上一页'],['nextScene','Next page','下一页'],['viewport','Preview width','预览宽度'],['scenes','Scenes','页面']])$('#'+id).setAttribute('aria-label',t(en,zh));const msg=$('#message');if(['Saved on this computer','已保存在本机'].includes(msg.textContent))msg.textContent=t('Saved on this computer','已保存在本机');if(['Unsaved changes','尚未保存'].includes(msg.textContent))msg.textContent=t('Unsaved changes','尚未保存');$('#uiLanguage').value=state.ui;document.querySelectorAll('[data-en]').forEach(n=>n.textContent=state.ui==='zh-CN'?n.dataset.zh:n.dataset.en);$('#save').textContent=t('Save','保存');$('#undo').textContent=t('Undo','撤销');$('#redo').textContent=t('Redo','重做');$('#history').textContent=t('History','历史');$('#exportHTML').textContent=t('Export HTML','导出 HTML');$('#backup').textContent=t('Project JSON','项目 JSON');workbench?.mode();}
async function libraries(){const {projects}=await json('/api/visual/projects',undefined,'GET');$('#library').innerHTML=projects.map(p=>`<option value="${x(p.id)}" ${p.unreadable?'disabled':''}>${x(p.title)}</option>`).join('');if(state.project)$('#library').value=state.project.id;const legacy=await json('/api/projects',undefined,'GET');$('#legacy').innerHTML=legacy.projects.filter(p=>!p.unreadable).map(p=>`<option value="${x(p.id)}">${x(p.title)}</option>`).join('');return projects;}
function activate(project){invalidateCandidates();familyOverrides=Object.create(null);clearTimeout(previewTimer);sequence++;state.project=project;$('#library').value=project.id;const requested=new URLSearchParams(location.search).get('scene');state.active=project.plan.scenes.some(s=>s.id===requested)?requested:project.plan.scenes[0].id;state.dirty=false;state.counter++;state.undo=[];state.redo=[];state.drafts.clear();state.render=null;state.measured=false;draw();schedulePreview();message(t('Saved on this computer','已保存在本机'));workbench?.selection();}
let sceneListKey='',thumbnailHeights=new Map();
function drawScenes(){
 if(!state.project)return;
 const scenes=state.project.plan.scenes,position=scenes.findIndex(s=>s.id===state.active),key=state.project.id+':'+state.counter+':'+state.ui;
 $('#moveUp').disabled=$('#previousScene').disabled=position===0;
 $('#moveDown').disabled=$('#nextScene').disabled=position===scenes.length-1;
 $('#count').textContent=scenes.length;$('#scenePosition').textContent=(position+1)+' / '+scenes.length;
 $('#deckName').textContent=state.project.document.title;
 if(key!==sceneListKey){sceneListKey=key;$('#scenes').innerHTML=scenes.map((s,i)=>{const b=state.project.document.blocks.find(b=>b.id===s.focalBlockId),title=b?.text||b?.label||s.id;return `<button class="scene-button" data-scene="${x(s.id)}" aria-label="${x((i+1)+'. '+title)}"><span class="scene-thumb" aria-hidden="true"></span><span class="scene-caption"><span class="scene-number">${String(i+1).padStart(2,'0')}</span><b>${x(title)}</b></span></button>`;}).join('');}
 for(const button of $('#scenes').querySelectorAll('[data-scene]'))button.setAttribute('aria-current',String(button.dataset.scene===state.active));
 $('#editSceneLabel').textContent=t('Page ','第 ')+(position+1)+t(' of ',' 页 / 共 ')+scenes.length+t('',' 页');
 $('#sceneTitle').textContent=state.project.document.blocks.find(b=>b.id===scene()?.focalBlockId)?.text||scene()?.id||'';
 thumbnails();
}
function thumbnails(){
 for(const holder of $('#scenes').querySelectorAll('.scene-thumb')){
  const id=holder.closest('[data-scene]').dataset.scene;
  if(!state.render){holder.replaceChildren();continue;}
  const url=state.render.artifactUrl+'?thumbnail='+encodeURIComponent(id);
  let frame=holder.querySelector('iframe');
  if(!frame||frame.getAttribute('src')!==url){frame=document.createElement('iframe');frame.src=url;frame.title=t('Page preview','页面缩略图')+' '+id;frame.setAttribute('sandbox','');frame.tabIndex=-1;frame.loading='lazy';holder.replaceChildren(frame);}
  const height=thumbnailHeights.get(id)||900,scale=Math.min(holder.clientWidth/1440,holder.clientHeight/height);
  frame.style.width='1440px';frame.style.height=height+'px';frame.style.transform=`scale(${scale})`;frame.style.left=(holder.clientWidth-1440*scale)/2+'px';
 }
}
function panel(name,{focus=false}={}){
 if(name==='direction')$('#workbenchStart').open=true;
 for(const [key,id,toggle]of [['direction','directionPanel','directionToggle'],['inspector','inspectorPanel','inspectorToggle']]){const open=key===name;$('#'+id).hidden=!open;$('#'+toggle).setAttribute('aria-expanded',String(open));$('.workspace').classList.toggle(key+'-open',open);}
 if(focus)$('#'+(name==='direction'?'workbenchPrompt':name==='inspector'?'title':'focusCanvas')).focus({preventScroll:true});
}
$('#directionToggle').onclick=()=>panel($('#directionPanel').hidden?'direction':null,{focus:true});
$('#inspectorToggle').onclick=()=>panel($('#inspectorPanel').hidden?'inspector':null,{focus:true});
$('#focusCanvas').onclick=()=>panel(null,{focus:true});for(const id of ['closeDirection','closeInspector'])$('#'+id).onclick=()=>{panel(null);$('#frameSpace').scrollIntoView({block:'nearest'});$('#focusCanvas').focus({preventScroll:true});};
document.addEventListener('deckweft:work-ready',()=>panel(null));
function selectScene(id,{focus=false}={}){if(!state.project?.plan.scenes.some(s=>s.id===id))return;state.active=id;drawScenes();drawEditor();drawCandidates();scale();$('#preview').contentWindow?.postMessage({type:'deckweft:select',sceneId:id},'*');if(focus)$('#scenes [aria-current="true"]').focus({preventScroll:true});}
function stepScene(delta){const scenes=state.project?.plan.scenes||[],index=scenes.findIndex(s=>s.id===state.active);if(scenes[index+delta])selectScene(scenes[index+delta].id);}
$('#expandCanvas').onclick=()=>{const button=$('#expandCanvas'),expanded=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(expanded));button.dataset.en=expanded?'Fit workspace':'Enlarge page';button.dataset.zh=expanded?'适合工作区':'放大页面';button.textContent=t(button.dataset.en,button.dataset.zh);scale();};
$('#previousScene').onclick=()=>stepScene(-1);$('#nextScene').onclick=()=>stepScene(1);
$('#scenes').addEventListener('keydown',e=>{const scenes=state.project?.plan.scenes||[];if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=scenes.findIndex(s=>s.id===e.target.closest('[data-scene]')?.dataset.scene);const next=e.key==='Home'?0:e.key==='End'?scenes.length-1:Math.max(0,Math.min(scenes.length-1,i+(e.key==='ArrowRight'?1:-1)));if(scenes[next])selectScene(scenes[next].id,{focus:true});});
const profileOptions={colorIntensity:['restrained','bold'],typographicContrast:['balanced','expressive'],density:['comfortable','compact'],motionIntensity:['off','subtle'],imageEmphasis:['balanced','large']};
const compositionLabels={'diagonal-cover':['Diagonal cover','斜切封面'],'chart-with-evidence-rail':['Chart with evidence rail','图表与说明栏'],'reading-flow':['Reading flow','流式阅读'],'photo-split':['Image-led split','图文分栏'],'violet-chapter':['Violet chapter','紫色章节']};
const choiceLabels={restrained:['Restrained','柔和'],bold:['Bold','鲜明'],balanced:['Balanced','均衡'],expressive:['Expressive','强烈'],comfortable:['Comfortable','舒展'],compact:['Compact','紧凑'],off:['Off','关闭'],subtle:['Subtle','轻微'],large:['Large','突出']};
const profileLabels={colorIntensity:['Color intensity','色彩强度'],typographicContrast:['Type contrast','字号对比'],density:['Density','内容密度'],motionIntensity:['Motion','动效强度'],imageEmphasis:['Image emphasis','图像比重']};
const familyLabels={statement:['Statement','观点陈述'],image:['Image narrative','图像叙事'],metric:['Oversized number','超大数值'],evidence:['Data evidence','数据证据'],comparison:['Comparison','比较'],process:['Process','流程']};
function activeFamily(){const s=scene();if(familyOverrides[s.id])return familyOverrides[s.id];const prefix=s.composition.split('-')[0];if(familyLabels[prefix])return prefix;const types=s.blockIds.map(id=>state.project.document.blocks.find(b=>b.id===id).type);return ['chart','image','metric','table','diagram'].map((k,i)=>types.includes(k)?['evidence','image','metric','comparison','process'][i]:null).find(Boolean)||'statement';}
function drawEditor(){const p=state.project,s=scene();if(!p||!s)return;drawAssetFields();$('#family').innerHTML=Object.entries(familyLabels).map(([key,label])=>`<option value="${key}" ${key===activeFamily()?'selected':''} ${!s.blockIds.some(id=>p.document.blocks.find(b=>b.id===id)?.type===({statement:'heading',image:'image',metric:'metric',evidence:'chart',comparison:'table',process:'diagram'})[key])?'disabled':''}>${x(t(...label))}</option>`).join('');$('#family').disabled=!!p.document.authorOverrides.sceneLocks?.some(l=>l.sceneId===s.id&&l.fields.includes('composition'));$('#title').value=p.document.title;$('#theme').value=s.theme;$('#composition').textContent=t('Composition: ','构图：')+t(...(compositionLabels[s.composition]||[s.composition,s.composition]));const lock=p.document.authorOverrides.sceneLocks?.find(l=>l.sceneId===s.id);$('#lockScene').checked=!!lock?.fields.some(f=>['theme','composition'].includes(f));$('#theme').disabled=lock?.fields.includes('theme')||false;$('#outputLanguage').value=p.document.locale;$('#audience').value=p.document.visualBrief?.audience||'';const noteIds=new Set((s.interactions||[]).flatMap(i=>(i.steps||[]).map(step=>step.explanationId)));$('#explanationJSON').value=state.drafts.get('_explanations')||JSON.stringify((p.document.explanations||[]).filter(n=>noteIds.has(n.id)),null,2);$('#explanationJSON').disabled=p.plan.scenes.some(sc=>(sc.interactions||[]).some(i=>p.document.authorOverrides.lockedBlockIds.includes(i.blockId)&&(i.steps||[]).some(step=>noteIds.has(step.explanationId))));$('#interactionJSON').value=state.drafts.get('_interactions')||JSON.stringify({interactions:s.interactions||[],cues:s.cues||[],...(s.motion?{motion:s.motion}:{})},null,2);drawInteractionFields();$('#lockInteractions').checked=!!lock?.fields.includes('interactions');$('#interactionJSON').disabled=!!lock?.fields.some(f=>['interactions','cues','motion'].includes(f));$('#sourceJSON').value=state.drafts.get('_sources')||JSON.stringify({sources:p.document.sources,sourceSnapshots:p.document.sourceSnapshots||[]},null,2);
 $('#profileFields').innerHTML=Object.entries(profileOptions).map(([key,options])=>`<label for="profile-${key}">${x(t(...profileLabels[key]))}</label><select id="profile-${key}" data-profile="${key}">${options.map(v=>`<option value="${v}" ${profile()[key]===v?'selected':''}>${x(t(...choiceLabels[v]))}</option>`).join('')}</select>`).join('');
 $('#fields').innerHTML=s.blockIds.map(id=>{const b=p.document.blocks.find(b=>b.id===id),locked=p.document.authorOverrides.lockedBlockIds.includes(id),disabled=locked?'disabled':'',key='field-'+id;let field='';
 if(['heading','paragraph','quote','callout','citation'].includes(b.type))field=`<label for="${key}">${x(t('Text','文字'))}</label><textarea id="${key}" data-text="${id}" ${disabled}>${x(b.text)}</textarea>`;
 else if(b.type==='code'){const {text,...metadata}=b,mixed=/\r(?!\n)/.test(text)||text.includes('\r\n')&&text.replaceAll('\r\n','').includes('\n');field=`<label for="${key}">${x(t('Exact code · whitespace retained','代码原文 · 保留空白')+(text.includes('\r\n')?' · CRLF':' · LF'))}</label><textarea id="${key}" data-text="${id}" spellcheck="false" ${disabled} ${mixed?'disabled':''}>${x(b.text)}</textarea>${mixed?`<p class="hint">${x(t('Mixed line separators: edit escaped JSON below.','混合换行：请在下方编辑转义 JSON。'))}</p>`:''}<label>${x(t('Language, emphasizedLines and sourceAnchor · JSON','语言、emphasizedLines 和 sourceAnchor · JSON'))}<textarea class="data-editor" ${mixed?'data-block':'data-code-meta'}="${id}" ${disabled}>${x(state.drafts.get(id)||JSON.stringify(mixed?b:metadata,null,2))}</textarea></label>`;}
 else if(b.type==='list')field=`<label for="${key}">${x(t('One item per line','每行一项'))}</label><textarea id="${key}" data-list="${id}" ${disabled}>${x(b.items.join('\n'))}</textarea>`;
 else if(b.type==='metric')field=`<label for="${key}">${x(t('Numeric value','数值'))}</label><input id="${key}" type="number" step="any" value="${b.value}" data-metric="${id}" ${disabled}><label>${x(t('Unit','单位'))}<input value="${x(b.unit)}" data-unit="${id}" ${disabled}></label><label>${x(t('Label','说明'))}<input value="${x(b.label)}" data-label="${id}" ${disabled}></label>`;
 else if(b.type==='chart'){const d=p.document.datasets.find(d=>d.id===b.datasetId);field=`<label for="${key}">${x(t('Typed dataset · JSON numbers / null gaps','类型化数据集 · JSON 数字／null 缺失'))}</label><textarea id="${key}" class="data-editor ${state.drafts.has(id)?'invalid':''}" data-dataset="${id}" ${disabled}>${x(state.drafts.get(id)||JSON.stringify(d,null,2))}</textarea><label>${x(t('Chart settings · stable identity, type and axes','图表设置 · 稳定身份、类型和坐标轴'))}<textarea data-block="${id}" class="data-editor" ${disabled}>${x(JSON.stringify(b,null,2))}</textarea></label>`;}
 else if(b.type==='image')field=`<label>${x(t('Alternative text','替代文字'))}<textarea data-alt="${id}" ${disabled}>${x(b.alt)}</textarea></label><p class="hint">${x(p.assets.find(a=>a.id===b.assetId)?.provenance||'')}</p>`;
 else field=`<label for="${key}">${x(t('Semantic block · JSON','语义内容块 · JSON'))}</label><textarea id="${key}" class="data-editor" data-block="${id}" ${disabled}>${x(state.drafts.get(id)||JSON.stringify(b,null,2))}</textarea>`;
 return `<section class="field-card"><span class="field-kind">${x(b.type)}</span>${field}<label class="check"><input type="checkbox" data-lock="${id}" ${locked?'checked':''}>${x(t('Lock this content','锁定此内容'))}</label></section>`;
 }).join('');
 const image=p.document.blocks.find(b=>s.blockIds.includes(b.id)&&b.type==='image'),crop=s.crops?.find(c=>c.blockId===image?.id)||{x:0,y:0,width:1,height:1};$('#cropFields').innerHTML=image?`<h2>${x(t('Image crop','图片裁切'))}</h2><div class="crop-grid">${['x','y','width','height'].map(k=>`<label>${k}<input type="number" min="0" max="1" step="0.01" value="${crop[k]}" data-crop="${k}" data-image="${image.id}" ${imageLocked(image.id)?'disabled':''}></label>`).join('')}</div>`:'';
 $('#imageOpen').disabled=!!(image&&(p.document.authorOverrides.lockedBlockIds.includes(image.id)||s.imageSlots?.length||lock?.fields.some(f=>['crops','imageSlots','blockIds'].includes(f))));status();}
function draw(){translate();drawScenes();drawEditor();status();}
function scale(){const width=Number($('#viewport').value),available=$('#frameSpace').clientWidth,height=Math.ceil(state.fit?.checks?.find(c=>c.sceneId===state.active)?.height||900),heightLimit=innerWidth>1000&&$('#expandCanvas').getAttribute('aria-pressed')!=='true'?Math.max(420,innerHeight-480):Infinity,s=Math.min(1,available/width,heightLimit/height);$('#preview').style.width=width+'px';$('#preview').style.height=height+'px';$('#preview').style.transform=`scale(${s})`;$('#preview').style.position='absolute';$('#preview').style.left=Math.max(0,(available-width*s)/2)+'px';$('#frameSpace').style.height=Math.ceil(height*s)+'px';}
new ResizeObserver(()=>{scale();thumbnails();}).observe($('#frameSpace'));$('#viewport').onchange=()=>{state.measured=false;scale();status();};
function schedulePreview(){clearTimeout(previewTimer);const run=++sequence;state.render=null;state.fit=null;state.measured=false;status();thumbnails();if(state.drafts.size){$('#preview').removeAttribute('src');return;}previewTimer=setTimeout(async()=>{const counter=state.counter;try{const r=await json('/api/visual/preview',{project:state.project});if(run!==sequence||counter!==state.counter)return;state.render=r;thumbnailHeights.clear();thumbnails();$('#preview').src=r.artifactUrl+'#scene='+encodeURIComponent(state.active);scale();}catch(e){if(run===sequence){error(e);$('#fit').textContent=t('Preview needs repair. Your edits remain here.','预览需要修复，编辑内容仍保留。');}}},200);}
addEventListener('message',async e=>{if(e.source===$('#preview').contentWindow&&e.data?.type==='deckweft:scene'&&e.data.renderHash===state.render?.renderHash){if(e.data.sceneId!==state.active)selectScene(e.data.sceneId);return;}if(e.source===$('#preview').contentWindow&&e.data?.type==='deckweft:web-error'&&e.data.renderHash===state.render?.renderHash){state.measured=false;status();error(new Error(e.data.message));return;}if(e.source!==$('#preview').contentWindow||e.data?.type!=='deckweft:web-fit'||!state.render||e.data.fit?.renderHash!==state.render.renderHash)return;const ticket=state.render.ticket;state.fit=e.data.fit;if(state.fit.viewport.width===1440){for(const c of state.fit.checks)thumbnailHeights.set(c.sceneId,c.height);thumbnails();}scale();try{if(!e.data.fit.ok)throw new Error(t('Some rendered content does not fit. Review this scene.','部分渲染内容不适合当前区域，请检查页面。'));await json('/api/visual/measure',{ticket,fit:e.data.fit});if(state.render?.ticket!==ticket)return;state.measured=true;status();}catch(err){error(err);}});
async function save(){if(!state.project||state.saving||state.drafts.size)return false;state.saving=true;status();const snapshot=structuredClone(state.project),counter=state.counter;try{const {project}=await json('/api/visual/projects/'+snapshot.id,{project:snapshot,expectedRevision:snapshot.revision.number},'PUT');if(state.project.id===snapshot.id){state.project.revision=project.revision;invalidateCandidates();if(counter===state.counter)state.dirty=false;}await libraries();schedulePreview();message(state.dirty?t('Newer edits remain unsaved.','较新的修改仍未保存。'):t('Saved on this computer','已保存在本机'));return true;}catch(e){error(e);return false;}finally{state.saving=false;status();}}
async function leave(){return !state.dirty&&!state.drafts.size||confirm(t('Leave these unsaved edits? Export Project JSON first to retain a backup.','离开尚未保存的修改？需要保留时，请先导出项目 JSON。'));}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#save').onclick=save;$('#undo').onclick=()=>moveHistory();$('#redo').onclick=()=>moveHistory(true);$('#backup').onclick=()=>{const value=state.drafts.size?{format:'deckweft-visual-draft',version:1,project:state.project,unappliedFields:Object.fromEntries(state.drafts)}:state.project;download(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}),'deckweft.visual.json');};
$('#exportHTML').onclick=async()=>{try{if(state.project?.extensions.deckweftWorkbench){await workbench.exportHTML();return;}const r=await api('/api/visual/export',{project:state.project,format:'html',ticket:state.render?.ticket});download(await r.blob(),'deckweft-visual.html');message(t('Standalone HTML exported with embedded local images.','已导出包含本地图片的独立 HTML。'));}catch(e){error(e);schedulePreview();}};
$('#scenes').onclick=e=>{const b=e.target.closest('[data-scene]');if(b)selectScene(b.dataset.scene);};
$('#library').onchange=async e=>{const id=e.target.value,counter=state.counter;if(!await leave()){e.target.value=state.project.id;return;}try{state.measured=false;state.render=null;status();const result=await json('/api/visual/projects/'+id,undefined,'GET');if(counter!==state.counter){$('#library').value=state.project.id;schedulePreview();throw new Error(t('Your edits changed while opening another deck. Open it again when ready.','打开其他文稿期间编辑发生变化，请准备好后重试。'));}activate(result.project);}catch(err){error(err);}};
$('#demo').onclick=async()=>{if(!await leave())return;state.measured=false;state.render=null;status();try{activate((await json('/api/visual/demo',{locale:state.ui})).project);await libraries();}catch(e){error(e);}};
$('#migrate').onclick=async()=>{if(!await leave())return;state.measured=false;state.render=null;status();try{const r=await json('/api/visual/migrate',{projectId:$('#legacy').value});activate(r.project);await libraries();message(r.warnings.join(' '));}catch(e){error(e);}};
$('#projectFile').onchange=async e=>{try{if(!await leave())return;const file=e.target.files[0];if(!file)return;if(file.size>1900000)throw new Error(t('Use JSON smaller than 1.9 MB.','请选择小于 1.9 MB 的 JSON。'));const project=JSON.parse(await file.text());state.measured=false;state.render=null;status();if(project.format!=='deckweft-visual-project')throw new Error(t('Import a visual project envelope. Draft backups must be repaired first.','请导入视觉项目，草稿备份需要先修复。'));activate((await json('/api/visual/import',{project})).project);await libraries();}catch(err){error(err);}finally{e.target.value='';}};
$('#audience').oninput=e=>changed(()=>{const d=state.project.document;d.visualBrief??={audience:'',outputLanguage:d.locale,profile:profile()};d.visualBrief.audience=e.target.value;});
$('#sourceJSON').oninput=e=>{try{const v=JSON.parse(e.target.value);if(!Array.isArray(v.sources)||!Array.isArray(v.sourceSnapshots)||Object.keys(v).some(k=>!['sources','sourceSnapshots'].includes(k)))throw new Error(t('Supply sources and sourceSnapshots arrays only.','请仅提供 sources 与 sourceSnapshots 数组。'));state.drafts.delete('_sources');changed(()=>{state.project.document.sources=v.sources;state.project.document.sourceSnapshots=v.sourceSnapshots;});status();}catch(err){state.drafts.set('_sources',e.target.value);sequence++;clearTimeout(previewTimer);state.render=null;state.measured=false;status();error(err);}};
$('#title').oninput=e=>changed(()=>state.project.document.title=e.target.value);
$('#fields').addEventListener('input',e=>{const n=e.target,b=state.project.document.blocks.find(b=>b.id===Object.values(n.dataset)[0]);if(!b||b.id!==Object.values(n.dataset)[0])return;if(n.dataset.lock)return;
 if(n.dataset.dataset||n.dataset.block||n.dataset.codeMeta){try{const parsed=JSON.parse(n.value);if(n.dataset.codeMeta){if(Object.hasOwn(parsed,'text'))throw Error('Edit exact code in the code text field.');parsed.text=b.text;}if(n.dataset.dataset&&(parsed.id!==b.datasetId||!Array.isArray(parsed.series)||parsed.series.some(s=>!Array.isArray(s.values)||s.values.some(v=>v!==null&&(typeof v!=='number'||!Number.isFinite(v))))))throw Error('Use finite numeric series or explicit null gaps; keep the dataset id.');if((n.dataset.block||n.dataset.codeMeta)&&(parsed.id!==b.id||parsed.type!==b.type))throw Error('Keep the semantic block id and type.');state.drafts.delete(b.id);n.classList.remove('invalid');changed(()=>{if(n.dataset.dataset)state.project.document.datasets[state.project.document.datasets.findIndex(d=>d.id===b.datasetId)]=parsed;else state.project.document.blocks[state.project.document.blocks.findIndex(v=>v.id===b.id)]=parsed;});status();}catch(err){state.drafts.set(b.id,n.value);sequence++;clearTimeout(previewTimer);state.render=null;state.measured=false;n.classList.add('invalid');status();error(err);}return;}
 changed(()=>{if(n.dataset.text)b.text=b.type==='code'&&b.text.includes('\r\n')?n.value.replaceAll('\r\n','\n').replaceAll('\n','\r\n'):n.value;if(n.dataset.list)b.items=n.value.split('\n');if(n.dataset.metric)b.value=n.value===''?null:Number(n.value);if(n.dataset.unit)b.unit=n.value;if(n.dataset.label)b.label=n.value;if(n.dataset.alt)b.alt=n.value;});
});
$('#fields').addEventListener('change',e=>{if(!e.target.dataset.lock)return;const id=e.target.dataset.lock;changed(()=>{const list=state.project.document.authorOverrides.lockedBlockIds;state.project.document.authorOverrides.lockedBlockIds=e.target.checked?[...new Set([...list,id])]:list.filter(v=>v!==id);},{fields:true});});
$('#resetDraft').onclick=()=>{state.drafts.clear();drawEditor();schedulePreview();message(t('Unapplied fields discarded; valid content retained.','已放弃未应用字段，保留有效内容。'));};
$('#theme').onchange=async e=>{const counter=state.counter;state.measured=false;state.render=null;status();try{const {project}=await json('/api/visual/theme',{project:state.project,sceneId:state.active,theme:e.target.value});if(counter!==state.counter)throw new Error(t('Edits changed while the theme was being prepared. Choose the theme again.','准备主题期间内容已改变，请重新选择主题。'));changed(()=>state.project=project,{fields:true});}catch(err){error(err);drawEditor();schedulePreview();}};
$('#lockScene').onchange=e=>changed(()=>{const a=state.project.document.authorOverrides;const existing=a.sceneLocks?.find(l=>l.sceneId===state.active),fields=(existing?.fields||[]).filter(f=>!['theme','composition'].includes(f));if(e.target.checked)fields.push('theme','composition');a.sceneLocks=(a.sceneLocks||[]).filter(l=>l.sceneId!==state.active);if(fields.length)a.sceneLocks.push({sceneId:state.active,fields});},{fields:true});
function setProfile(key,value){const d=state.project.document;d.visualBrief??={audience:'',outputLanguage:d.locale,profile:profile()};d.visualBrief.profile[key]=value;}
$('#profileFields').onchange=e=>{if(e.target.dataset.profile)changed(()=>setProfile(e.target.dataset.profile,e.target.value));};
$('#outputLanguage').onchange=e=>changed(()=>{state.project.document.locale=e.target.value;const d=state.project.document;d.visualBrief??={audience:'',outputLanguage:d.locale,profile:profile()};d.visualBrief.outputLanguage=e.target.value;});
$('#cropFields').onchange=e=>{if(!e.target.dataset.crop)return;changed(()=>{const s=scene(),id=e.target.dataset.image;s.crops??=[];let c=s.crops.find(c=>c.blockId===id);if(!c){c={blockId:id,x:0,y:0,width:1,height:1};s.crops.push(c);}c[e.target.dataset.crop]=e.target.value===''?null:Number(e.target.value);});};
$('#contentTab').onclick=()=>tab(false);$('#designTab').onclick=()=>tab(true);function tab(design){$('#contentPanel').hidden=design;$('#designPanel').hidden=!design;$('#contentTab').setAttribute('aria-selected',String(!design));$('#designTab').setAttribute('aria-selected',String(design));}
$('#uiLanguage').onchange=e=>{state.ui=e.target.value;localStorage.setItem('deckweft.visual.ui',state.ui);draw();};
$('#history').onclick=async()=>{try{const r=await json('/api/visual/projects/'+state.project.id+'/history',undefined,'GET');$('#historyList').innerHTML=r.snapshots.length?r.snapshots.map(s=>`<button class="history-item" data-revision="${s.revision}" ${s.unreadable?'disabled':''}>r${s.revision} · ${x(s.title)} · ${x(s.savedAt)}</button>`).join(''):x(t('No earlier versions. Edit and save to create one.','还没有旧版本，编辑并保存后会创建。'));$('#snapshot').hidden=$('#restore').hidden=true;state.snapshot=null;$('#historyDialog').showModal();}catch(e){error(e);}};
$('#historyClose').onclick=()=>$('#historyDialog').close();$('#historyList').onclick=async e=>{const b=e.target.closest('[data-revision]');if(!b)return;try{state.snapshot=await json('/api/visual/projects/'+state.project.id+'/history/'+b.dataset.revision,undefined,'GET');$('#snapshot').value=JSON.stringify(state.snapshot.project,null,2);$('#snapshot').hidden=$('#restore').hidden=false;}catch(err){error(err);}};
$('#restore').onclick=async()=>{if(!state.snapshot||!await leave())return;try{state.measured=false;state.render=null;status();const r=await json('/api/visual/projects/'+state.project.id+'/history/'+state.snapshot.project.revision.number+'/restore',{mode:'copy',snapshotHash:state.snapshot.sha256,requestId:crypto.randomUUID().replaceAll('-','')});activate(r.project);await libraries();$('#historyDialog').close();}catch(e){error(e);}};
$('#imageOpen').onclick=()=>$('#imageDialog').showModal();$('#imageClose').onclick=()=>$('#imageDialog').close();$('#imageForm').onsubmit=async e=>{e.preventDefault();try{const file=$('#imageFile').files[0];if(!file||file.size>1300000)throw new Error(t('Choose a PNG smaller than 1.3 MB.','请选择小于 1.3 MB 的 PNG。'));const bytes=new Uint8Array(await file.arrayBuffer());let str='';for(const b of bytes)str+=String.fromCharCode(b);const metadata={provenance:$('#imageProvenance').value,license:$('#imageLicense').value,allowedUse:$('#imageUse').value,alt:$('#imageAlt').value,fallback:$('#imageFallback').value};const {asset}=await json('/api/visual/assets',{base64:btoa(str),metadata});const prior=state.project.assets.find(a=>a.id===asset.id);if(prior&&JSON.stringify(prior)!==JSON.stringify(asset))throw Error(t('This image hash already has different source or rights metadata. Resolve it explicitly.','此图片哈希已有不同来源或许可，请明确处理差异。'));changed(()=>{const p=state.project,s=scene();if(!p.assets.some(a=>a.id===asset.id))p.assets.push(asset);let image=p.document.blocks.find(b=>s.blockIds.includes(b.id)&&b.type==='image');if(image){image.assetId=asset.id;image.alt=metadata.alt;}else{image={id:'image_'+crypto.randomUUID().replaceAll('-','').slice(0,16),type:'image',sourceIds:[],assetId:asset.id,alt:metadata.alt,factual:false};p.document.blocks.push(image);s.blockIds.push(image.id);}},{fields:true});$('#imageDialog').close();}catch(err){error(err);}};
addEventListener('beforeunload',e=>{if(state.dirty||state.drafts.size){e.preventDefault();e.returnValue='';}});addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='s'){e.preventDefault();save();}});
async function boot(){translate();status();state.token=(await(await fetch('/api/session')).json()).token;const projects=await libraries(),id=new URLSearchParams(location.search).get('project')||projects.find(p=>!p.unreadable)?.id;if(id)activate((await json('/api/visual/projects/'+id,undefined,'GET')).project);else{panel('direction');message(t('Add your words to begin.','提供原文，即可开始。'));}status();}
workbench=mountWorkbench({state,json,api,activate,libraries,save,leave,download,error,translate});
boot().catch(error);

$('#family').onchange=e=>{familyOverrides[state.active]=e.target.value;invalidateCandidates();message(t('Compare again to measure this family.','请重新比较并测量此类构图。'));};
async function movePage(offset){const counter=state.counter;state.measured=false;state.render=null;status();try{const {project}=await json('/api/visual/move',{project:state.project,sceneId:state.active,offset});if(counter!==state.counter)throw Error(t('Edits changed; retry page movement.','编辑已改变，请重试移动页面。'));changed(()=>state.project=project,{fields:true});}catch(e){error(e);schedulePreview();}}
$('#moveUp').onclick=()=>movePage(-1);$('#moveDown').onclick=()=>movePage(1);
function drawCandidates(){if(!candidateState)return;const i=state.project.plan.scenes.findIndex(s=>s.id===state.active);for(const [k,set]of candidateState.sets.entries()){const card=$(`[data-candidate="${k}"]`);if(!card)continue;const descriptor=set.scenes[i],label=candidateState.families[descriptor.family]?.variants.find(v=>v[0]===descriptor.id);card.querySelector('h3').textContent=(k+1)+' · '+(label?t(label[1],label[2]):descriptor.id);const fit=set.fits?.[i];card.querySelector('.candidate-fit').textContent=fit?(fit.ok?t('✓ Fits · ','✓ 排版通过 · ')+Math.ceil(fit.height)+'px'+(fit.features?' · '+t('density ','密度 ')+Math.round(fit.features.density*100)+'% · '+t('image ','图片 ')+Math.round(fit.features.imageRatio*100)+'%':''):fit.reasons.join(' · ')):t('Measuring fonts and layout…','正在测量字体与排版…');card.querySelector('[data-select-candidate]').disabled=!fit?.ok;card.querySelector('iframe').contentWindow?.postMessage({type:'deckweft:select',sceneId:state.active},'*');}$('#rhythm').disabled=!candidateState.sets.every(s=>s.fits);scaleCandidates();}
function scaleCandidates(){document.querySelectorAll('.candidate-window').forEach(n=>{const s=n.clientWidth/1440,f=n.querySelector('iframe');f.style.transform=`scale(${s})`;n.style.height=(900*s)+'px';});}
addEventListener('resize',scaleCandidates);
$('#compare').onclick=async()=>{if(!state.project||state.drafts.size)return;invalidateCandidates();const run=candidateRun,counter=state.counter;$('#compare').disabled=true;$('#candidateStatus').textContent=t('Preparing three complete candidate decks…','正在准备三份完整候选文稿…');try{const result=await json('/api/visual/candidates',{project:state.project,families:familyOverrides});if(run!==candidateRun||counter!==state.counter)return;candidateState=result;$('#candidates').innerHTML=result.sets.map((s,k)=>`<article class="candidate-card" data-candidate="${k}"><h3></h3><div class="candidate-window"><iframe title="${x(t('Composition candidate ','构图候选 ')+(k+1))}" sandbox="allow-scripts" src="${s.artifactUrl}#scene=${encodeURIComponent(state.active)}"></iframe></div><p class="candidate-fit" role="status"></p><button data-inspect-candidate="${k}">${x(t('View larger','放大查看'))}</button><button data-select-candidate="${k}" disabled>${x(t('Use this composition','使用此构图'))}</button></article>`).join('');drawCandidates();}catch(e){error(e);$('#candidateStatus').textContent=e.message;}finally{$('#compare').disabled=false;}};
addEventListener('message',async e=>{const current=candidateState;if(!current)return;const k=[...document.querySelectorAll('.candidate-card iframe')].findIndex(f=>f.contentWindow===e.source);if(k>=0&&e.data?.type==='deckweft:web-error'){error(new Error(e.data.message));$('#candidateStatus').textContent=e.data.message;return;}if(k<0||e.data?.type!=='deckweft:web-fit'||e.data.fit?.renderHash!==current.sets[k].renderHash)return;try{const r=await json('/api/visual/candidate-measure',{ticket:current.sets[k].ticket,fit:e.data.fit});if(current!==candidateState)return;current.sets[k].fits=r.fits;drawCandidates();if(current.sets.every(s=>s.fits))$('#candidateStatus').textContent=t('Three full decks measured at 1440px. Select a passing composition, or apply deck rhythm.','三份完整文稿已在 1440px 测量，可选择通过的构图或应用整稿节奏。');}catch(err){if(current===candidateState){error(err);$('#candidateStatus').textContent=err.message;}}});
async function selectComposition(index){const current=candidateState,counter=state.counter;if(!current)return;state.measured=false;state.render=null;status();try{const r=await json(index===undefined?'/api/visual/rhythm':'/api/visual/select-candidate',{project:state.project,tickets:current.sets.map(s=>s.ticket),...(index===undefined?{}:{sceneId:state.active,index})});if(counter!==state.counter||current!==candidateState)throw Error(t('Edits changed. Compare again.','编辑已改变，请重新比较。'));const modified=changed(()=>state.project=r.project,{fields:true});if(!modified)schedulePreview();if(r.report){$('#rhythmReport').innerHTML=`<p>${x(t('Story rhythm cost: ','整篇节奏成本：')+r.report.cost)}</p><ol>${r.report.scenes.map(s=>`<li>${x(s.sceneId+' · '+s.id)}<small>${x(t('Beat: ','段落：')+(s.narrative?.phase||'context')+' · '+t('Focus: ','焦点：')+s.focus+' · '+t('Density: ','密度：')+Math.round(s.density*100)+'% · '+t('Image: ','图片：')+Math.round(s.imageRatio*100)+'% · '+s.theme+' / '+s.colorMode)}</small>${s.transition?`<small>${x(t('Repeated with previous page: ','与前页重复：')+Object.entries(s.transition.parts).filter(([,v])=>v>0).map(([k])=>t(...({geometry:['composition','构图'],focus:['focus','焦点'],density:['density','密度'],color:['color mode','色彩模式'],imageRatio:['image ratio','图片比例']})[k])).join(', '))}</small>`:''}</li>`).join('')}</ol>`;}message(t('Composition applied. Review the preview and save.','构图已应用，请查看预览后保存。'));}catch(e){error(e);schedulePreview();}}
$('#candidateClose').onclick=()=>$('#candidateDialog').close();
$('#candidates').onclick=e=>{const inspect=e.target.closest('[data-inspect-candidate]');if(inspect&&candidateState){const set=candidateState.sets[Number(inspect.dataset.inspectCandidate)];$('#candidateTitle').textContent=t('Candidate ','候选 ')+(set.index+1);$('#largeCandidate').src=set.artifactUrl+'#scene='+encodeURIComponent(state.active);$('#candidateDialog').showModal();scaleCandidates();return;}const b=e.target.closest('[data-select-candidate]');if(b)selectComposition(Number(b.dataset.selectCandidate));};$('#rhythm').onclick=()=>selectComposition();

$('#compositionDemo').onclick=async()=>{if(!await leave())return;try{activate((await json('/api/visual/composition-demo',{locale:state.ui})).project);await libraries();}catch(e){error(e);}};

function currentImage(){return state.project?.document.blocks.find(b=>b.id===selectedImage&&scene()?.blockIds.includes(b.id)&&b.type==='image');}
function imageLocked(blockId=currentImage()?.id){const b=state.project?.document.blocks.find(b=>b.id===blockId),fields=state.project?.document.authorOverrides.sceneLocks?.find(l=>l.sceneId===state.active)?.fields||[];return fields.some(f=>['crops','imageSlots'].includes(f))||!!(b&&state.project.document.authorOverrides.lockedBlockIds.includes(b.id));}
function localSlot(){const b=currentImage(),s=scene(),asset=state.project.assets.find(a=>a.id===b.assetId),existing=s.imageSlots?.find(v=>v.blockId===b.id);if(existing)return structuredClone(existing);const c=s.crops?.find(v=>v.blockId===b.id)||{x:0,y:0,width:1,height:1};return {id:'hero',blockId:b.id,brief:{role:'illustration',requiredWidth:Math.max(1,Math.min(320,Math.floor(asset.width*c.width))),requiredHeight:Math.max(1,Math.min(240,Math.floor(asset.height*c.height))),focalPoint:{x:c.x+c.width/2,y:c.y+c.height/2},safeRegion:{x:c.x,y:c.y,width:c.width,height:c.height},factual:!!b.factual,sourceId:b.factual?b.sourceIds[0]||'':'',backend:'none'},display:'crop',aspect:asset.width*c.width/(asset.height*c.height)};}
function drawAssetFields(){const p=state.project,s=scene(),images=p.document.blocks.filter(b=>s.blockIds.includes(b.id)&&b.type==='image');if(!images.some(b=>b.id===selectedImage))selectedImage=images[0]?.id||'';assetInspection=null;$('#sourceCatalog').replaceChildren();sourceEntries=[];const locked=imageLocked();$('#sourceImport').disabled=locked;$('#imageAlternative').disabled=!!p.document.authorOverrides.sceneLocks?.some(l=>l.sceneId===s.id&&l.fields.includes('composition'));
 if(!images.length){$('#assetFields').innerHTML=`<p class="hint">${x(t('Import or extract an image to add a named slot. All current content stays.','导入或提取图片以添加具名槽，现有内容全部保留。'))}</p>`;return;}
 const slot=localSlot(),b=currentImage(),asset=p.assets.find(a=>a.id===b.assetId),d=locked?'disabled':'';
 const number=(id,label,value,min=0,max=1,step=.01)=>`<label>${x(label)}<input id="${id}" type="number" min="${min}" max="${max}" step="${step}" value="${value}" ${d}></label>`;
 $('#assetFields').innerHTML=`<label for="slotImage">${x(t('Image binding','图片绑定'))}</label><select id="slotImage">${images.map(v=>`<option value="${v.id}" ${v.id===b.id?'selected':''}>${x(v.alt)}</option>`).join('')}</select><label for="slotName">${x(t('Named slot','具名槽'))}</label><input id="slotName" value="${x(slot.id)}" maxlength="64" ${d}><label for="slotRole">${x(t('Role','素材用途'))}</label><select id="slotRole" ${d}>${Object.entries({photo:['Photo','照片'],'product-screenshot':['Product screenshot','产品截图'],illustration:['Illustration / concept','插图／概念图'],background:['Background','背景']}).map(([k,l])=>`<option value="${k}" ${k===slot.brief.role?'selected':''}>${x(t(...l))}</option>`).join('')}</select><div class="crop-grid">${number('slotW',t('Minimum width (pixels)','最低宽度（像素）'),slot.brief.requiredWidth,1,8192,1)}${number('slotH',t('Minimum height (pixels)','最低高度（像素）'),slot.brief.requiredHeight,1,8192,1)}</div><label class="check"><input id="slotFactual" type="checkbox" ${slot.brief.factual?'checked':''} ${d}>${x(t('Factual source evidence','事实性来源证据'))}</label><label for="slotSource">${x(t('Document source reference','文稿来源引用'))}</label><select id="slotSource" ${d}><option value="">${x(t('No factual reference','无事实引用'))}</option>${p.document.sources.map(source=>`<option value="${source.id}" ${source.id===slot.brief.sourceId?'selected':''}>${x(source.title)}</option>`).join('')}</select><h3>${x(t('Focal point / protected region (0–1)','焦点／受保护区域（0–1）'))}</h3><p class="hint">${x(t('Mark the subject yourself. These are original-image coordinates; no subject detection runs.','请自行标记主体；坐标相对原图，不运行主体识别。'))}</p><div class="crop-grid">${number('focalX',t('Focus x','焦点 x'),slot.brief.focalPoint.x)}${number('focalY',t('Focus y','焦点 y'),slot.brief.focalPoint.y)}${['x','y','width','height'].map(k=>number('safe-'+k,t('Safe '+k,({x:'保护区 x',y:'保护区 y',width:'保护区宽度',height:'保护区高度'})[k]),slot.brief.safeRegion[k])).join('')}</div><label for="slotDisplay">${x(t('Display mode','展示方式'))}</label><select id="slotDisplay" ${d}><option value="crop" ${slot.display==='crop'?'selected':''}>${x(t('Keep current crop','保留当前裁切'))}</option><option value="contain" ${slot.display==='contain'?'selected':''}>${x(t('Contain complete original','完整展示原图'))}</option></select><button id="slotApply" ${d}>${x(t('Apply direction','应用素材方向'))}</button><button id="downloadOriginal">${x(t('Download unchanged original','下载未修改的原件'))}</button><button id="slotInspect">${x(t('Inspect original & crop candidates','查看原图与裁切候选'))}</button><canvas id="subjectCanvas" width="520" height="360" hidden aria-label="Original image with author-protected region"></canvas><p class="hint" id="assetIdentity">${x(t('Native hash: ','保真图哈希：')+asset.hash)}<br>${x(asset.original?t('Original: ','原件：')+asset.original.hash:t('Legacy original PNG retained','保留旧版 PNG 原件'))}<br>${x(asset.license+' · '+asset.provenance)}</p><div id="cropVariants"></div><label for="reuseAsset">${x(t('Reuse an existing asset','复用文稿已有素材'))}</label><select id="reuseAsset">${p.assets.map(a=>`<option value="${a.id}">${x(a.alt)}</option>`).join('')}</select><button id="reuseApply" ${d}>${x(t('Attach selected asset','绑定所选素材'))}</button>`;
}
async function mutateAsset(route,data){const counter=state.counter,sceneId=state.active,project=state.project;state.measured=false;state.render=null;status();try{const r=await json('/api/visual/'+route,{project,sceneId,blockId:currentImage()?.id,...data});if(counter!==state.counter||sceneId!==state.active)throw Error(t('The page or edits changed; retry on the current page.','页面或编辑已改变，请在当前页重试。'));if(!changed(()=>state.project=r.project,{fields:true}))schedulePreview();return true;}catch(e){error(e);schedulePreview();return false;}}
$('#assetFields').onchange=e=>{if(e.target.id==='slotImage'){selectedImage=e.target.value;drawAssetFields();}};
$('#assetFields').onclick=async e=>{const id=e.target.id;if(id==='slotApply'){const slot=localSlot(),num=id=>$('#'+id).value===''?null:Number($('#'+id).value);slot.id=$('#slotName').value;slot.brief={role:$('#slotRole').value,requiredWidth:num('slotW'),requiredHeight:num('slotH'),focalPoint:{x:num('focalX'),y:num('focalY')},safeRegion:Object.fromEntries(['x','y','width','height'].map(k=>[k,num('safe-'+k)])),factual:$('#slotFactual').checked,sourceId:$('#slotSource').value,backend:'none'};slot.display=$('#slotDisplay').value;await mutateAsset('image-slot',{action:'configure',slot});}
 if(id==='downloadOriginal'){try{const r=await api('/api/visual/asset-original',{project:state.project,assetId:currentImage().assetId});const disposition=r.headers.get('Content-Disposition')||'',name=disposition.match(/filename="([^"]+)"/)?.[1]||'deckweft-original.png';download(await r.blob(),name);}catch(err){error(err);}}
 if(id==='slotInspect'){const counter=state.counter,active=state.active,b=currentImage();try{const [inspection,original]=await Promise.all([json('/api/visual/image-slot',{project:state.project,sceneId:active,blockId:b.id,action:'inspect'}),json('/api/visual/asset-inspection',{project:state.project,assetId:b.assetId})]);if(counter!==state.counter||active!==state.active||b.id!==currentImage()?.id)return;assetInspection=inspection;const image=new Image();image.src=original.native;await image.decode();if(counter!==state.counter||active!==state.active||b.id!==currentImage()?.id)return;const canvas=$('#subjectCanvas'),ctx=canvas.getContext('2d'),s=Math.min(canvas.width/image.naturalWidth,canvas.height/image.naturalHeight),w=image.naturalWidth*s,h=image.naturalHeight*s,ox=(canvas.width-w)/2,oy=(canvas.height-h)/2;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,ox,oy,w,h);const safe=inspection.slot.brief.safeRegion,f=inspection.slot.brief.focalPoint;ctx.strokeStyle='#e7512f';ctx.lineWidth=4;ctx.strokeRect(ox+safe.x*w,oy+safe.y*h,safe.width*w,safe.height*h);ctx.beginPath();ctx.arc(ox+f.x*w,oy+f.y*h,7,0,Math.PI*2);ctx.stroke();canvas.hidden=false;const locked=imageLocked();$('#cropVariants').innerHTML=`<p>${x(t('Orange: protected subject; circle: focal point.','橙框：受保护区域；圆点：焦点。'))}</p>`+inspection.variants.map(v=>`<div class="crop-choice"><b>${x(t(...({portrait:['Portrait 3:4','竖版 3:4'],square:['Square 1:1','方形 1:1'],wide:['Wide 16:9','宽幅 16:9']})[v.id]))}</b><p>${x(v.ok?t('✓ Protected region fits','✓ 可保全受保护区域'):v.code==='PROTECTED_REGION'?t('Protected subject cannot fit. Choose contain.','无法保全受保护主体，请选择完整展示。'):v.code==='ASSET_QUALITY'?t('Not enough visible source pixels for this slot.','可见原图像素不足以满足此槽要求。'):v.reason)}</p><button data-safe-aspect="${v.aspect}" ${!v.ok||locked?'disabled':''}>${x(t('Use safe crop','使用安全裁切'))}</button></div>`).join('')+`<button data-contain="true" ${locked?'disabled':''}>${x(t('Contain complete image in 16:9','在 16:9 中完整展示原图'))}</button>`;}catch(err){error(err);}}
 if(e.target.dataset.safeAspect)await mutateAsset('image-slot',{action:'crop',mode:'crop',aspect:Number(e.target.dataset.safeAspect)});
 if(e.target.dataset.contain)await mutateAsset('image-slot',{action:'crop',mode:'contain',aspect:16/9});
 if(id==='reuseApply')await mutateAsset('image-slot',{action:'reuse',assetId:$('#reuseAsset').value});
};
$('#sourceImport').onclick=()=>$('#sourceDialog').showModal();$('#sourceClose').onclick=()=>$('#sourceDialog').close();
$('#sourceForm').onsubmit=async e=>{e.preventDefault();const counter=state.counter,active=state.active,blockId=currentImage()?.id;$('#sourceSubmit').disabled=true;try{const file=$('#sourceFile').files[0];if(!file||file.size>1300000)throw Error(t('Choose a source smaller than 1.3 MB.','请选择小于 1.3 MB 的原件。'));const raw=new Uint8Array(await file.arrayBuffer()),mime=sourceMime(raw),original=(await json('/api/visual/asset-upload',{mime,base64:base64(raw)})).blob;const converted=await decodeLocalSource(file,original,$('#webEncoding').value);const upload=async(blob,mime)=>(await json('/api/visual/asset-upload',{mime,base64:base64(new Uint8Array(await blob.arrayBuffer()))})).blob;const native=original.mime==='image/png'?original:await upload(converted.native,'image/png'),web=converted.web?await upload(converted.web,converted.web.type):undefined,metadata={provenance:$('#sourceProvenance').value,license:$('#sourceLicense').value,allowedUse:$('#sourceUse').value,alt:$('#sourceAlt').value,fallback:$('#sourceFallback').value};const {asset}=await json('/api/visual/asset-import',{original,native,web,metadata,origin:$('#sourceOrigin').value});if(counter!==state.counter||active!==state.active||blockId!==currentImage()?.id)throw Error(t('The page changed during import. Original bytes remain local; select the intended page and retry.','导入期间页面已改变。原件字节已留在本地，请选择目标页后重试。'));if(await mutateAsset('image-slot',{action:'attach',asset}))$('#sourceDialog').close();}catch(err){error(err);}finally{$('#sourceSubmit').disabled=false;}};
$('#sourceScan').onclick=async()=>{const counter=state.counter,active=state.active;try{const {entries}=await json('/api/visual/asset-catalog',{});if(counter!==state.counter||active!==state.active)return;sourceEntries=entries;$('#sourceCatalog').innerHTML=entries.length?`<label for="sourceChoice">${x(t('Saved source image','已保存的来源图片'))}</label><select id="sourceChoice">${entries.map((r,i)=>`<option value="${i}">${x(r.title+' · '+r.asset.alt+' · '+r.kind)}</option>`).join('')}</select><button id="extractSource" ${imageLocked()?'disabled':''}>${x(t('Extract and attach — preserve source','提取并绑定，保留来源文稿'))}</button>`:x(t('No registered source images in this local library.','当前本地库没有已注册的来源图片。'));}catch(e){error(e);}};
$('#sourceCatalog').onclick=async e=>{if(e.target.id!=='extractSource')return;const entry=sourceEntries[Number($('#sourceChoice').value)];if(entry)await mutateAsset('asset-extract',{kind:entry.kind,sourceProjectId:entry.projectId,assetId:entry.asset.id});};
$('#imageAlternative').onclick=()=>mutateAsset('asset-alternative',{});

$('#assetDemo').onclick=async()=>{if(!await leave())return;try{activate((await json('/api/visual/asset-demo',{locale:state.ui})).project);state.active='violet';draw();schedulePreview();await libraries();}catch(e){error(e);}};

$('#componentDemo').onclick=async()=>{if(!await leave())return;try{activate((await json('/api/visual/component-demo',{locale:state.ui})).project);state.active='component-line';draw();schedulePreview();await libraries();}catch(e){error(e);}};

$('#interactionDemo').onclick=async()=>{if(!await leave())return;try{activate((await json('/api/visual/interaction-demo',{locale:state.ui})).project);state.active='component-line';draw();schedulePreview();await libraries();}catch(e){error(e);}};
$('#interactionJSON').oninput=e=>{try{const value=JSON.parse(e.target.value);if(!Array.isArray(value.interactions)||!Array.isArray(value.cues)||Object.keys(value).some(k=>!['interactions','cues','motion'].includes(k)))throw Error(t('Supply interactions, cues and optional motion only.','仅可提供 interactions、cues 和可选 motion。'));state.drafts.delete('_interactions');changed(()=>{const s=scene();s.interactions=value.interactions;s.cues=value.cues;if(value.motion)s.motion=value.motion;else delete s.motion;});status();}catch(err){state.drafts.set('_interactions',e.target.value);sequence++;clearTimeout(previewTimer);state.render=null;state.measured=false;status();error(err);}};
$('#lockInteractions').onchange=e=>changed(()=>{const d=state.project.document;d.authorOverrides.sceneLocks??=[];let lock=d.authorOverrides.sceneLocks.find(l=>l.sceneId===state.active);if(!lock){lock={sceneId:state.active,fields:[]};d.authorOverrides.sceneLocks.push(lock);}lock.fields=lock.fields.filter(f=>!['interactions','cues','motion'].includes(f));if(e.target.checked)lock.fields.push('interactions','cues','motion');d.authorOverrides.sceneLocks=d.authorOverrides.sceneLocks.filter(l=>l.fields.length);},{fields:true});

$('#explanationJSON').oninput=e=>{try{const notes=JSON.parse(e.target.value),ids=new Set((scene().interactions||[]).flatMap(i=>(i.steps||[]).map(step=>step.explanationId)));if(!Array.isArray(notes)||notes.some(n=>!n||!ids.has(n.id))||new Set(notes.map(n=>n.id)).size!==notes.length)throw Error(t('Edit uniquely identified explanation content referenced by this scene.','仅编辑本页引用的唯一身份说明内容。'));state.drafts.delete('_explanations');changed(()=>{const old=state.project.document.explanations||[],incoming=new Map(notes.map(n=>[n.id,n]));state.project.document.explanations=[...old.map(n=>ids.has(n.id)?incoming.get(n.id):n).filter(Boolean),...notes.filter(n=>!old.some(v=>v.id===n.id))];});status();}catch(err){state.drafts.set('_explanations',e.target.value);sequence++;clearTimeout(previewTimer);state.render=null;state.measured=false;status();error(err);}};

function drawInteractionFields(){
 const p=state.project,s=scene(),locks=p.document.authorOverrides.sceneLocks?.find(l=>l.sceneId===s.id)?.fields||[];
 $('#enableInteractions').disabled=!!state.drafts.size||locks.some(f=>['interactions','cues'].includes(f));
 $('#sceneMotion').value=s.motion?.policy||'';$('#sceneMotion').disabled=locks.includes('motion');
 const notes=new Map((p.document.explanations||[]).map(n=>[n.id,n]));
 $('#explanationFields').innerHTML=(s.interactions||[]).filter(i=>i.kind==='steps').map(i=>`<fieldset class="field-card"><legend>${x(t('Step explanations','分步讲解'))}</legend>${i.steps.map((step,k)=>{const n=notes.get(step.explanationId),locked=p.plan.scenes.some(sc=>(sc.interactions||[]).some(v=>p.document.authorOverrides.lockedBlockIds.includes(v.blockId)&&v.steps?.some(st=>st.explanationId===step.explanationId)));return `<label>${k+1} · ${x(t('Label','标题'))}<input maxlength="100" data-explanation="${x(n.id)}" data-note-field="label" value="${x(n.label)}" ${locked?'disabled':''}></label><label>${x(t('Explanation','说明'))}<textarea maxlength="2000" data-explanation="${x(n.id)}" data-note-field="text" ${locked?'disabled':''}>${x(n.text)}</textarea></label>`;}).join('')}</fieldset>`).join('');
}
$('#enableInteractions').onclick=()=>{try{if(state.drafts.size)throw Error(t('Repair unapplied edits first.','请先修复未应用的编辑。'));const next=addExplanatoryInteractions(state.project,state.active);changed(()=>{state.project=next;},{fields:true});}catch(e){error(e);}};
$('#sceneMotion').onchange=e=>changed(()=>{if(e.target.value)scene().motion={policy:e.target.value,durationMs:e.target.value==='off'?0:240};else delete scene().motion;},{fields:true});
$('#explanationFields').addEventListener('change',e=>{const n=e.target;if(!n.dataset.explanation)return;if(!n.value.trim()){error(new Error(t('An explanation cannot be empty.','说明不能为空。')));drawInteractionFields();return;}changed(()=>{state.project.document.explanations.find(v=>v.id===n.dataset.explanation)[n.dataset.noteField]=n.value;},{fields:true});});

let openingRequest=null;
$('#useInteractionOpening').onclick=()=>{
 if(!state.measured||state.drafts.size||!state.render)return;
 openingRequest={id:crypto.randomUUID(),counter:state.counter,sceneId:state.active,renderHash:state.render.renderHash};
 $('#preview').contentWindow.postMessage({type:'deckweft:request-opening',...openingRequest},'*');
};
addEventListener('message',e=>{
 const r=openingRequest;if(!r||e.source!==$('#preview').contentWindow||e.data?.type!=='deckweft:opening'||e.data.id!==r.id)return;
 openingRequest=null;if(state.counter!==r.counter||state.active!==r.sceneId||state.render?.renderHash!==r.renderHash||e.data.renderHash!==r.renderHash||e.data.sceneId!==r.sceneId)return;
 try{const next=useInteractionOpening(state.project,r.sceneId,e.data.state);changed(()=>{state.project=next;},{fields:true});message(t('Opening view applied. Save and export to retain this selection.','已应用开场状态，保存并导出即可保留此选择。'));}catch(err){error(err);}
});
